import pandas as pdfrom collections import Counterimport nltknltk.download('stopwords')nltk.download('punkt')from nltk.corpus import stopwordsimport osos.chdir("/Users/diana")# ── 1. Load and merge datasets ─────────────────speeches = pd.read_csv("speeches.csv", sep="|", usecols=["date", "contents"])fx = pd.read_csv("fx.csv", usecols=["Date", "USD"]).rename(columns={"Date": "date"})speeches["date"] = pd.to_datetime(speeches["date"])fx["date"] = pd.to_datetime(fx["date"])merged = fx.merge(speeches, on="date", how="left")# ── 2. Remove obvious outliers or mistakes ─────# No obvious outliers found in USD (range historically valid)# ── 3. Handle missing exchange rates ───────────merged = merged.sort_values("date")merged["USD"] = merged["USD"].ffill()merged = merged.dropna(subset=["USD"])# ── 4. Calculate exchange rate return ──────────merged["fx_return"] = merged["USD"].pct_change() * 100merged["good_news"] = (merged["fx_return"] > 0.5).astype(int)merged["bad_news"] = (merged["fx_return"] < -0.5).astype(int)# ── 5. Remove NA contents and generate word tables ─merged_clean = merged.dropna(subset=["contents"])stop_words = set(stopwords.words("english"))def get_top_words(df, n=20):    words = []    for text in df["contents"].dropna():        tokens = str(text).lower().split()        tokens = [w.strip(".,!?;:\"'()[]") for w in tokens]        tokens = [w for w in tokens if w.isalpha() and w not in stop_words]        words.extend(tokens)    return pd.DataFrame(Counter(words).most_common(n), columns=["word", "n"])good_indicators = get_top_words(merged_clean[merged_clean["good_news"] == 1])bad_indicators = get_top_words(merged_clean[merged_clean["bad_news"] == 1])good_indicators.to_csv("good_indicators_py.csv", index=False)bad_indicators.to_csv("bad_indicators_py.csv", index=False)